sys_script_include.script:
var CPMAccess = Class.create();
CPMAccess.prototype = {
  initialize: function() {
    this.K = new CPMConst();
    this.T = this.K.TABLE;
    this.util = new CPMUtil();
    this.userId = gs.getUserID();
    this._admin = null;
  },

  // compliance team: has the role and, when "admin_group" is set, belongs to that group.
  // gs.hasRole() alone is true for every system admin
  isAdmin: function() {
    if (this._admin === null) {
      var group = this.util.prop('admin_group', '');
      this._admin = gs.hasRole(this.K.ROLE.ADMIN) && (!group || gs.getUser().isMemberOf(group));
    }
    return this._admin;
  },

  // only the owner of a control can upload for it, admins included
  isOwnerOf: function(mapping) {
    return !!mapping.getValue('owner') && mapping.getValue('owner') == this.userId;
  },

  // the team sees everything, an owner only their own controls
  canSee: function(mapping) {
    return this.isAdmin() || this.isOwnerOf(mapping);
  },

  // ids of the CIs and services the current user owns a control on
  ownedTargetIds: function() {
    var ids = [];
    var ga = new GlideAggregate(this.T.MAPPING);
    ga.addQuery('owner', this.userId);
    ga.addQuery('active', true);
    ga.addAggregate('COUNT');
    ga.groupBy('target');
    ga.query();
    while (ga.next()) ids.push(ga.getValue('target'));
    return ids;
  },

  // may the user open this page? The team always, an owner only with a control on it
  canViewTarget: function(targetId) {
    if (this.isAdmin()) return true;
    var gr = new GlideRecord(this.T.MAPPING);
    gr.setWorkflow(false);
    gr.addQuery('target', targetId);
    gr.addQuery('owner', this.userId);
    gr.addQuery('active', true);
    gr.setLimit(1);
    gr.query();
    return gr.hasNext();
  },

  type: 'CPMAccess'
};
